        'dress_code', jsonb_build_object('status','queer_self_expression_context_with_rules_now_dependent_on_each_named_host_venue','source_urls',to_jsonb(array['https://www.visitberlin.de/de/schwuz-berlin','https://www.schwuz.de/']::text[]),'checked_at','2026-08-06T00:00:00Z'),
