        'crowd_mix', jsonb_build_object('status','queer_trans_femme_nonbinary_friend_artist_international_and_neighbourhood_led_mix','source_urls',to_jsonb(array['https://www.silverfuture.net/','https://wanderlog.com/place/details/2202814/silverfuture','https://www.tripadvisor.com.au/Attraction_Review-g187323-d2559428-Reviews-Silver_Future-Berlin.html']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'dress_code', jsonb_build_object('status','informal_neukoelln_self_expression_smoking_room_and_published_fixed_ramp context','source_urls',to_jsonb(array['https://www.silverfuture.net/kontakt/','https://www.silverfuture.net/events-1/']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','durable_queer_feminist_identity_current_community_events_mixed_service_reports_and_partial_access_information','source_urls',to_jsonb(array['https://www.silverfuture.net/','https://www.silverfuture.net/kontakt/','https://wanderlog.com/place/details/2202814/silverfuture']::text[]),'checked_at','2026-08-06T00:00:00Z')
