    (1104::bigint, jsonb_build_object(
      'queue_wait', 'This is a cocktail-led Mitte bar, not a notorious selector door. Weeknights are easier for a seat; Friday and Saturday can turn the compact room into a standing, dancing crowd. Arrive before 10pm for conversation, later for pulse. Current listings disagree slightly on opening time, so verify same-day.',
      'best_nights', 'Friday and Saturday deliver the fullest version: accurate cocktails, driving beats and a room that often dances late. A midweek visit keeps the industrial-dark interior intimate and lets the bar craft show. It works as a polished first drink near Hackescher Markt or a stylish final stop after Museum Island.',
      'crowd_mix', 'Gay men are prominent, joined by a visibly mixed LGBTQ+ crowd, straight friends, Mitte after-work guests and travellers. It is urban and queer without demanding one scene identity. The central address brings more visitors than a deep neighbourhood bar, while returning regulars and the bar team keep it personal.',
      'dress_code', 'Aim casual but considered: black tailoring, a crisp tee, jewellery, leather accents or a sharp date-night look all suit the dark industrial room. There is no published door code and no need for techno cosplay. The bar rewards polish more than costume; comfortable shoes help once weekend DJ energy rises.',
      'staff_inclusivity', 'Current editorial and guide coverage praises charming, warm service, accurate drinks and welcome across genders and orientations. Public reviews include older material and no venue is friction-free, but the recent professional consensus is unusually aligned: sophisticated without becoming icy or exclusionary.',
      'venue_classification', 'active_stylish_mitte_lgbtq_cocktail_bar_with_industrial_design_weekend_djs_gay_male_core_and_broad_mixed_audience',
      'source_urls', to_jsonb(array['https://www.thecovenberlin.com/','https://www.top10berlin.de/location/coven-3989/','https://www.falstaff.com/de/bars/the-coven','https://www.tripadvisor.com.au/Attraction_Review-g187323-d12690245-Reviews-The_Coven_Bar-Berlin.html','https://berlin.gaycities.com/bars/306114-thecoven']::text[]),
      'topic_evidence', jsonb_build_object(
        'queue_wait', jsonb_build_object('status','current_small_cocktail_bar_weeknight_seating_and_friday_saturday_standing_dance_peak_without_hard_door','source_urls',to_jsonb(array['https://www.top10berlin.de/location/coven-3989/','https://www.falstaff.com/de/bars/the-coven']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'best_nights', jsonb_build_object('status','current_weekend_dj_dance_energy_and_midweek_cocktail_conversation_pattern','source_urls',to_jsonb(array['https://www.top10berlin.de/location/coven-3989/','https://www.falstaff.com/de/bars/the-coven']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'crowd_mix', jsonb_build_object('status','current_gay_male_prominent_broad_lgbtq_straight_friend_after_work_traveller_and_regular_mix','source_urls',to_jsonb(array['https://www.top10berlin.de/location/coven-3989/','https://www.falstaff.com/de/bars/the-coven','https://berlin.gaycities.com/bars/306114-thecoven']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'dress_code', jsonb_build_object('status','stylish_industrial_cocktail_and_weekend_dance_context_without_published_door_code','source_urls',to_jsonb(array['https://www.thecovenberlin.com/','https://www.top10berlin.de/location/coven-3989/','https://www.falstaff.com/de/bars/the-coven']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','aligned_current_editorial_warm_charming_professional_service_and_all_orientation_welcome consensus','source_urls',to_jsonb(array['https://www.top10berlin.de/location/coven-3989/','https://www.falstaff.com/de/bars/the-coven','https://www.tripadvisor.com.au/Attraction_Review-g187323-d12690245-Reviews-The_Coven_Bar-Berlin.html']::text[]),'checked_at','2026-08-06T00:00:00Z')
      ),
