    (821::bigint, jsonb_build_object(
      'queue_wait', 'There is no queue or door: this is an unstaffed public cruising zone around Bremer Weg and the Lion Bridge, not a venue. Activity builds after dusk and can be weather-dependent. Never wait alone for a promised crowd; keep a clear route back to a lit path and tell someone where you are.',
      'best_nights', 'Warm dry evenings bring the most movement, with later hours feeling more explicitly sexual. Daylight is calmer for learning the paths; darkness offers anonymity but raises navigation and robbery risk. After the July 2026 Pride attack near Tiergarten, follow current police guidance and avoid any restricted area.',
      'crowd_mix', 'Mostly gay, bi and curious adult men—Berliners, commuters and visitors—circulate rather than settle into one social crowd. Ages and body types vary, and nobody can promise a local-to-tourist ratio in an anonymous park. Presence is not consent: interest should be reciprocal, readable and easy to withdraw.',
      'dress_code', 'Ordinary weather-ready clothes and shoes with grip are smarter than a costume. Carry little, keep your phone and wallet secure, use protection and take anything you bring away again. Stay on routes you can identify, respect the public park and never photograph or expose another person without consent.',
      'staff_inclusivity', 'There is no host, door team or awareness crew to protect you. The space’s queer history does not equal supervised safety, and past robbery reports matter. Go sober enough to choose, set boundaries clearly, leave with a trusted person when possible and call emergency services rather than confronting aggression.',
      'venue_classification', 'active_historic_unstaffed_public_park_gay_cruising_area_near_bremer_weg_and_lion_bridge_with_consent_navigation_theft_and_current_public_safety_cautions',
      'record_status', 'active_public_space_safety_sensitive_no_staff_no_guaranteed_activity_follow_current_authority_guidance',
      'source_urls', to_jsonb(array['https://dertiergarten.de/cruising-area/','https://www.gaymapper.com/gay-cruising-spot/berlin/tiergarten','https://gay-szene.net/tiergarten-in-berlin/11561/eintrag.html','https://www.iwwit.de/wp-content/uploads/cruising-guide-IWWIT-2026.pdf','https://apnews.com/article/8b3c8ded8033ab246cb55f7bd1c47e2f']::text[]),
      'topic_evidence', jsonb_build_object(
        'queue_wait', jsonb_build_object('status','unstaffed_public_cruising_zone_without_queue_weather_and_after_dark_activity_with_route_safety_needs','source_urls',to_jsonb(array['https://dertiergarten.de/cruising-area/','https://www.gaymapper.com/gay-cruising-spot/berlin/tiergarten','https://www.iwwit.de/wp-content/uploads/cruising-guide-IWWIT-2026.pdf']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'best_nights', jsonb_build_object('status','warm_dry_evening_activity_daylight_orientation_darkness_risk_and_july_2026_current_public_safety_context','source_urls',to_jsonb(array['https://gay-szene.net/tiergarten-in-berlin/11561/eintrag.html','https://www.iwwit.de/wp-content/uploads/cruising-guide-IWWIT-2026.pdf','https://apnews.com/article/8b3c8ded8033ab246cb55f7bd1c47e2f']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'crowd_mix', jsonb_build_object('status','adult_gay_bi_curious_men_local_commuter_and_visitor_mix_with_anonymous_consent_context','source_urls',to_jsonb(array['https://dertiergarten.de/cruising-area/','https://www.gaymapper.com/gay-cruising-spot/berlin/tiergarten','https://www.iwwit.de/wp-content/uploads/cruising-guide-IWWIT-2026.pdf']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'dress_code', jsonb_build_object('status','weather_ready_low_value_belongings_safer_sex_no_photography_public_space_and_navigation guidance','source_urls',to_jsonb(array['https://www.iwwit.de/wp-content/uploads/cruising-guide-IWWIT-2026.pdf','https://gay-szene.net/tiergarten-in-berlin/11561/eintrag.html']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','no_staff_or_awareness_team_historic_queer_use_balanced_against_robbery_and_current_public_safety evidence','source_urls',to_jsonb(array['https://gay-szene.net/tiergarten-in-berlin/11561/eintrag.html','https://www.iwwit.de/wp-content/uploads/cruising-guide-IWWIT-2026.pdf','https://apnews.com/article/8b3c8ded8033ab246cb55f7bd1c47e2f']::text[]),'checked_at','2026-08-06T00:00:00Z')
